mapper.select:
SELECT t.id, t.bus_no AS partCode, t.name AS partName, t.parent_id AS parentId, t.status_enum AS status, CASE WHEN COUNT(c.id) > 0 THEN 1 ELSE 0 END AS hasChildren FROM dia_body_structure t LEFT JOIN dia_body_structure c ON c.parent_id = t.id AND c.is_deleted = 0 WHERE t.is_deleted = 0
AND (t.bus_no LIKE CONCAT('%', #{keyword}, '%') OR t.name LIKE CONCAT('%', #{keyword}, '%'))
AND t.parent_id IS NULL
AND t.parent_id = #{parentId}
AND t.status_enum = #{status}
GROUP BY t.id, t.bus_no, t.name, t.parent_id, t.status_enum ORDER BY t.bus_no ASC
